// SysORTableKey is the decoded INDEX of one sysORTable row, one field per
// part in INDEX order. It is comparable and usable as a map key.
type SysORTableKey struct {
	SysORIndex uint32
}

var sysORTableIndexShapes = []snmp.IndexShape{{Kind: snmp.IndexInteger}}

// decodeSysORTableKey decodes the instance suffix of one sysORTable row. ok is false
// when the suffix does not match the declared INDEX; the key is then zero.
func decodeSysORTableKey(idx snmp.OID) (SysORTableKey, bool) {
	var parts [1]snmp.IndexValue
	if !snmp.DecodeIndexInto(parts[:], idx, sysORTableIndexShapes) {
		return SysORTableKey{}, false
	}
	return SysORTableKey{SysORIndex: parts[0].Integer}, true
}

// SysORTableRow is one row of sysORTable. Key is the decoded INDEX; a
// suffix that does not match the declared INDEX leaves it zero, and
// [SysORTableRow.KeyValid] reports which. The remaining fields are
// populated only for columns the caller passed to Walk(). Use
// [SysORTableRow.Observed] to tell a reported zero from a column the
// agent never answered.
// The zero value has no observed columns. Concurrent reads are safe;
// callers must synchronize mutation of the row or its referenced data.
type SysORTableRow struct {
	Key         SysORTableKey
	keyValid    bool
	SysORID     snmp.OID
	SysORDescr  string
	SysORUpTime uint32

	// observed carries one bit per column of this table, in
	// column-OID order, set when the walk decoded a value for
	// that column on this row.
	observed [1]uint64
}

// KeyValid reports whether the row's instance suffix decoded as the declared
// INDEX. A false result means Key is zero and the agent's suffix did not
// have the declared shape; the row's columns are still populated.
func (r SysORTableRow) KeyValid() bool {
	return r.keyValid
}

// Observed reports whether col returned a value for this row. A column
// the agent answered reads true even when the answer was zero or empty;
// a column that was requested but never landed, one that was not passed
// to Walk, and any column of another table all read false.
func (r SysORTableRow) Observed(col snmp.AnyColumn) bool {
	switch col.Key() {
	case SysORID.Key():
		return r.observed[0]&(1<<0) != 0
	case SysORDescr.Key():
		return r.observed[0]&(1<<1) != 0
	case SysORUpTime.Key():
		return r.observed[0]&(1<<2) != 0
	}

	return false
}

// SysORTableWalker streams selected columns of sysORTable.
// The zero value is not usable; construct via SysORTable.Walk(ctx, sess, cols...).
// Iteration is single-use and single-consumer; Close and Err are safe concurrently.
type SysORTableWalker struct {
	rw   *snmp.ColumnWalker
	cols []snmp.AnyColumn
}

// Iter yields complete selected-column rows in numeric OID suffix order
// (192.168.0.2 precedes 192.168.0.10). It retains one batch per selected
// column. Breaking iteration stops retrieval. A decode error omits the
// failing row and later rows; already delivered rows remain valid. Check Err.
// A row whose suffix does not decode as the declared INDEX is still yielded,
// with a zero Key and KeyValid false; the yielded OID is its raw suffix.
func (tw *SysORTableWalker) Iter() iter.Seq2[snmp.OID, SysORTableRow] {
	return func(yield func(snmp.OID, SysORTableRow) bool) {
		for idx, cells := range tw.rw.Iter() {
			var row SysORTableRow
			row.Key, row.keyValid = decodeSysORTableKey(idx)
			for _, cell := range cells {
				rv := cell.Value
				var derr error
				switch tw.cols[cell.Column].Key() {
				case SysORID.Key():
					vb, vbErr := rv.Decode()
					if vbErr != nil {
						derr = vbErr
					} else {
						dv, dErr := SysORID.Decode(vb)
						if dErr != nil {
							derr = dErr
						} else {
							row.SysORID = dv
							row.observed[0] |= 1 << 0
						}
					}
				case SysORDescr.Key():
					vb, vbErr := rv.Decode()
					if vbErr != nil {
						derr = vbErr
					} else {
						dv, dErr := SysORDescr.Decode(vb)
						if dErr != nil {
							derr = dErr
						} else {
							row.SysORDescr = dv
							row.observed[0] |= 1 << 1
						}
					}
				case SysORUpTime.Key():
					if v, okRaw := snmp.RawTimeTicks(rv); okRaw {
						row.SysORUpTime = uint32(v)
						row.observed[0] |= 1 << 2
					} else {
						vb, vbErr := rv.Decode()
						if vbErr != nil {
							derr = vbErr
						} else {
							dv, dErr := SysORUpTime.Decode(vb)
							if dErr != nil {
								derr = dErr
							} else {
								row.SysORUpTime = dv
								row.observed[0] |= 1 << 2
							}
						}
					}
				}
				if derr != nil {
					tw.rw.Fail(derr)
					return
				}
			}
			if !yield(idx, row) {
				return
			}
		}
	}
}

// Err returns the underlying walker's terminal error, or nil if
// the walk completed naturally.
func (tw *SysORTableWalker) Err() error {
	return tw.rw.Err()
}

// sysORTableT is the singleton type of SysORTable.
type sysORTableT struct{}

// SysORTable is the descriptor for the sysORTable table.
var SysORTable sysORTableT

// Close stops retrieval. It is idempotent and safe during iteration.
func (tw *SysORTableWalker) Close() {
	tw.rw.Close()
}

// Walk lazily retrieves only selected columns with bounded defaults.
// Rows are the union of selected values in numeric OID index order.
// No columns means no rows or requests. Duplicate selections are ignored.
// Unknown or foreign columns fail before I/O with [snmp.ErrForeignColumn].
func (t sysORTableT) Walk(ctx context.Context, sess snmp.Session, cols ...snmp.AnyColumn) *SysORTableWalker {
	return t.WalkWithOptions(ctx, sess, snmp.TableWalkOptions{}, cols...)
}

// Descriptor returns the table as a [snmp.TableDescriptor]: its root OID, its
// change indicator when the MIB declares one, and the Go type of its row key.
// The descriptor is a value; hold it without the row or walker types to probe
// for the table or declare it as a dependency.
func (sysORTableT) Descriptor() snmp.TableDescriptor {
	return snmp.TableDescriptor{
		Indicator: SysORTableIndicator,
		KeyType:   "SysORTableKey",
		Root:      snmp.MustOID(1, 3, 6, 1, 2, 1, 1, 9),
	}
}

// WalkWithOptions is Walk with request sizing and per-call controls.
// SNMPv1 remains unsupported. Parent cancellation is an error; stopping iteration is successful.
func (sysORTableT) WalkWithOptions(ctx context.Context, sess snmp.Session, options snmp.TableWalkOptions, cols ...snmp.AnyColumn) *SysORTableWalker {
	seen := make(map[string]bool)
	var selected []snmp.AnyColumn
	var roots []snmp.OID
	for _, c := range cols {
		switch c.Key() {
		case SysORID.Key(), SysORDescr.Key(), SysORUpTime.Key():
		default:
			w := snmp.WalkColumns(ctx, sess, nil, options)
			w.Fail(errs.Wrapf(snmp.ErrForeignColumn, "sysORTable.Walk: column %s", c.OID()))
			return &SysORTableWalker{rw: w}
		}
		if seen[c.Key()] {
			continue
		}
		seen[c.Key()] = true
		selected = append(selected, c)
		roots = append(roots, c.OID())
	}
	return &SysORTableWalker{
		cols: selected,
		rw:   snmp.WalkColumns(ctx, sess, roots, options),
	}
}

// decodeSysORTableRow decodes one row of SysORTable from the supplied
// VarBinds. Each VarBind's OID determines which row field it populates
// (via the column's last sub-id). VarBinds with unknown column-ids are
// ignored. Absent columns leave their field at its zero value.
func decodeSysORTableRow(idx snmp.OID, vbs []snmp.VarBind) (SysORTableRow, error) {
	var row SysORTableRow
	row.Key, row.keyValid = decodeSysORTableKey(idx)

	for _, vb := range vbs {
		o := vb.GetHeader().OID
		if o.Len() == 0 {
			continue
		}
		entryLen := snmp.MustOID(1, 3, 6, 1, 2, 1, 1, 9, 1).Len()
		if o.Len() <= entryLen {
			continue
		}
		colID := o.At(entryLen)
		switch colID {
		case 2:
			dv, derr := SysORID.Decode(vb)
			if derr != nil {
				return row, derr
			}
			row.SysORID = dv
			row.observed[0] |= 1 << 0
		case 3:
			dv, derr := SysORDescr.Decode(vb)
			if derr != nil {
				return row, derr
			}
			row.SysORDescr = dv
			row.observed[0] |= 1 << 1
		case 4:
			dv, derr := SysORUpTime.Decode(vb)
			if derr != nil {
				return row, derr
			}
			row.SysORUpTime = dv
			row.observed[0] |= 1 << 2
		}
	}

	return row, nil
}

// equalSysORTableRow compares two SysORTableRow values for equality.
// Used by [snmp.Watcher] to compute ChangeKindModified emits. Field-by-
// field with the type-appropriate comparator (bytes.Equal for []byte,
// OID.Equal for OID, time.Time.Equal for time.Time, == for everything else).
func equalSysORTableRow(a SysORTableRow, b SysORTableRow) bool {
	return a.Key == b.Key && a.keyValid == b.keyValid && a.observed == b.observed && a.SysORID.Equal(b.SysORID) && a.SysORDescr == b.SysORDescr && a.SysORUpTime == b.SysORUpTime
}

// mergeSysORTableRow merges the values decoded from vbs into dst, leaving fields
// whose columns are not present in vbs unchanged. Used by [snmp.Watcher]
// to maintain per-row state under partial-column fetches (Counter-tier,
// Static-tier). Best-effort: individual VarBind decode failures are
// silently skipped rather than propagated, because partial-fetch ticks
// surface transient errors through [snmp.Watcher.LastTickErr] at the
// call-site granularity rather than per-VarBind.
func mergeSysORTableRow(dst *SysORTableRow, vbs []snmp.VarBind) {
	for _, vb := range vbs {
		o := vb.GetHeader().OID
		if o.Len() == 0 {
			continue
		}
		entryLen := snmp.MustOID(1, 3, 6, 1, 2, 1, 1, 9, 1).Len()
		if o.Len() <= entryLen {
			continue
		}
		colID := o.At(entryLen)
		switch colID {
		case 2:
			dv, derr := SysORID.Decode(vb)
			if derr == nil {
				dst.SysORID = dv
				dst.observed[0] |= 1 << 0
			}
		case 3:
			dv, derr := SysORDescr.Decode(vb)
			if derr == nil {
				dst.SysORDescr = dv
				dst.observed[0] |= 1 << 1
			}
		case 4:
			dv, derr := SysORUpTime.Decode(vb)
			if derr == nil {
				dst.SysORUpTime = dv
				dst.observed[0] |= 1 << 2
			}
		}
	}
}

// SysORTableWatcher is a table-aware Watcher over SysORTable.
// The zero value is not usable; construct via SysORTable.Watch(ctx, sess, cols, opts...).
// Use a single iterator. The other methods may be called concurrently.
type SysORTableWatcher struct {
	w *snmp.Watcher[SysORTableRow]
}

// Iter returns the range-over-func view of the Watcher's event stream.
// See [snmp.Watcher.Iter] for the contract.
func (tw *SysORTableWatcher) Iter() iter.Seq2[snmp.OID, snmp.WatchEvent[SysORTableRow]] {
	return tw.w.Iter()
}

// Err returns the underlying Watcher's terminal error, or nil if it
// completed naturally. See [snmp.Watcher.Err].
func (tw *SysORTableWatcher) Err() error {
	return tw.w.Err()
}

// Close signals the Watcher's tick goroutine to terminate. Idempotent.
// See [snmp.Watcher.Close].
func (tw *SysORTableWatcher) Close() error {
	return tw.w.Close()
}

// Fallback reports whether the Watcher has transitioned to fallback
// mode. See [snmp.Watcher.Fallback].
func (tw *SysORTableWatcher) Fallback() bool {
	return tw.w.Fallback()
}

// LastTickErr returns the most-recent transient per-tick error.
// See [snmp.Watcher.LastTickErr].
func (tw *SysORTableWatcher) LastTickErr() error {
	return tw.w.LastTickErr()
}

// TableRoot returns the OID of the table this Watcher operates over.
func (tw *SysORTableWatcher) TableRoot() snmp.OID {
	return tw.w.TableRoot()
}

// Watch opens a long-lived watch on SysORTable.
//
// cols selects the columns whose values are reported on every emitted
// event. opts override cadence bounds, per-column tier classifications,
// fallback behavior, and other policy — see [snmp.WatchOption] for the
// full set.
//
// cols is a slice rather than variadic because opts is variadic and
// Go forbids two variadic parameters.
//
// Events emitted on this stream:
//   - ChangeKindAdded    — Row populated, Prev always nil.
//   - ChangeKindModified — Row is current state. Prev is nil unless
//     the caller passed [snmp.WithPrevRow]; when
//     set, Prev carries the previous Row.
//   - ChangeKindRemoved  — Row carries the last-known state at the
//     time the row disappeared. Prev is nil.
//
// The returned Watcher must be Closed when the caller is done; iteration
// exit alone does not free the underlying goroutine until Close.
//
// On validation failure (invalid cadence bounds, tier override of the
// indicator column, etc.) Watch returns a Watcher whose Err() returns
// the cause immediately; range loops exit without emitting events and
// Close is a no-op.
func (sysORTableT) Watch(ctx context.Context, sess snmp.Session, cols []snmp.AnyColumn, opts ...snmp.WatchOption) *SysORTableWatcher {
	allOpts := append([]snmp.WatchOption{snmp.WithTierLookup(ColumnTier)}, opts...)
	w, _ := snmp.NewWatcher[SysORTableRow](ctx, sess, SysORTableIndicator, cols, decodeSysORTableRow, equalSysORTableRow, mergeSysORTableRow, allOpts...)

	return &SysORTableWatcher{w: w}
}

// sNMPv2MIBOIDDispatch maps column wire keys ([snmp.OID.WireKey]) to their
// typed AnyColumn for fast
// lookup during table-walk decoding. Per-MIB-module — no global
// registry; cross-package callers should consult OIDDispatch().
var sNMPv2MIBOIDDispatch = map[string]snmp.AnyColumn{
	snmp.MustOID(1, 3, 6, 1, 2, 1, 1, 9, 1, 2).WireKey(): SysORID,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 1, 9, 1, 3).WireKey(): SysORDescr,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 1, 9, 1, 4).WireKey(): SysORUpTime,
}

// OIDDispatch returns a shallow copy of the package's wire-key →
// AnyColumn map. The copy isolates callers from accidental mutation
// of the package-internal map.
func OIDDispatch() map[string]snmp.AnyColumn {
	out := make(map[string]snmp.AnyColumn, len(sNMPv2MIBOIDDispatch))
	for k, v := range sNMPv2MIBOIDDispatch {
		out[k] = v
	}
	return out
}

// sNMPv2MIBColumnTiers maps column wire keys ([snmp.OID.WireKey]) to their
// snmp.Tier classification.
// Tier classification drives the Watcher's scheduler — counters fire
// on their own cadence, state columns refresh on indicator advance,
// and indicator columns drive the change-detection probe itself.
// See snmp.Tier and snmp.Watcher for the consumption contract.
var sNMPv2MIBColumnTiers = map[string]snmp.Tier{
	snmp.MustOID(1, 3, 6, 1, 2, 1, 1, 9, 1, 2).WireKey(): snmp.TierState,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 1, 9, 1, 3).WireKey(): snmp.TierState,
	snmp.MustOID(1, 3, 6, 1, 2, 1, 1, 9, 1, 4).WireKey(): snmp.TierIndicator,
}

// ColumnTier returns the codegen-classified [snmp.Tier] for col, or
// snmp.TierUnknown when col's OID is not known to this package. The
// generated Watch methods install this function via
// [snmp.WithTierLookup]; returning TierUnknown lets the runtime fall
// back to its wire-Kind heuristic for columns this package does not
// classify. Caller overrides via [snmp.WithColumnTier] still win.
func ColumnTier(col snmp.AnyColumn) snmp.Tier {
	if col == nil {
		return snmp.TierUnknown
	}
	t, ok := sNMPv2MIBColumnTiers[col.Key()]
	if !ok {
		return snmp.TierUnknown
	}
	return t
}

// SysORTableIndicator is the scalar change indicator for sysORTable.
// The Watcher Gets sysORLastChange on each tick; when the value
// advances the full table is walked and diffed against the snapshot.
// See [snmp.NewScalarIndicator] and [snmp.Watcher] for the contract.
// Discovered by mibgen structural rule: scalar named after the table plus an indicator suffix.
var SysORTableIndicator = snmp.MustChangeIndicator(snmp.NewScalarIndicator(snmp.MustOID(1, 3, 6, 1, 2, 1, 1, 8), snmp.KindTimeTicks, []snmp.OID{snmp.MustOID(1, 3, 6, 1, 2, 1, 1, 9)}))
